import {createGrowthViews} from './growth-views-2cd6b06ecb42.mjs';
import {APP_VERSION} from './version-2cd6b06ecb42.mjs';
import * as D from './domain-2cd6b06ecb42.mjs';
import {compositionCard,growthOverview} from './insights-2cd6b06ecb42.mjs';
import {diaryCollection} from './diary-2cd6b06ecb42.mjs';
import {themeSettings} from './theme-2cd6b06ecb42.mjs';
import {onboardingBanner} from './onboarding-2cd6b06ecb42.mjs';
import {phoneCard,phoneSettings} from './phone-ui-2cd6b06ecb42.mjs';
export const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const icons={today:'◷',growth:'✧',plans:'⚑',memory:'▤',insights:'▥',settings:'⚙'};
export const titles={today:'今日',growth:'成长',plans:'阶段',memory:'闪回',insights:'统计',settings:'本地数据'};
export const num=n=>n>0&&n<0.01?'< 0.01':Number(n.toFixed(2)).toLocaleString('zh-CN');
export const progressNum=n=>n>0&&n<0.01?'< 0.01':Number((Math.floor(n*100)/100).toFixed(2)).toLocaleString('zh-CN');
export const duration=n=>n<1?(n>0?`${num(n*60)}秒`:'0分钟'):n<60?`${num(n)}分钟`:`${Math.floor(n/60)}小时${n%60>=0.01?' '+num(n%60)+'分':''}`;
export const clock=(ms,zone='Asia/Shanghai',seconds=false)=>new Intl.DateTimeFormat('zh-CN',{timeZone:zone,hour:'2-digit',minute:'2-digit',...(seconds?{second:'2-digit'}:{}),hourCycle:'h23'}).format(ms);
const longDate=d=>new Intl.DateTimeFormat('zh-CN',{month:'long',day:'numeric',weekday:'long',timeZone:'UTC'}).format(new Date(d+'T12:00Z'));
const button=(action,label,cls='',id='')=>`<button type="button" class="${cls}" data-action="${action}" ${id?`data-id="${e(id)}"`:''}>${label}</button>`;
export const empty=(title,body,action='',label='')=>`<div class="empty"><span class="empty-star" aria-hidden="true">✧</span><h3>${title}</h3><p>${body}</p>${action?button(action,label,'secondary'):''}</div>`;
export const bar=ratio=>`<div class="progress" role="progressbar" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.floor(Math.max(0,Math.min(1,ratio))*100)}"><span style="width:${Math.max(0,Math.min(ratio<1?.995:1,ratio))*100}%"></span></div>`;
export function shell(state,ui,content){
  const nav=Object.keys(titles).map(key=>`<button type="button" data-nav="${key}" class="nav-item ${(ui.navPage||ui.page)===key?'active':''}" ${(ui.navPage||ui.page)===key?'aria-current="page"':''}><span aria-hidden="true">${icons[key]}</span><b>${titles[key]}</b></button>`).join('');
  return `<aside class="sidebar"><div class="brand"><div class="brand-mark">N<span>◇</span></div><p>NO GAME<br>NO LIFE<span>日常，也有自己的光。</span></p></div><nav aria-label="主导航">${nav}</nav><div class="sidebar-bottom"><i></i> 只属于你的本地记录<small>LOCAL EDITION / ${APP_VERSION}</small></div></aside>
  <main id="main" tabindex="-1"><header class="topbar"><div><span class="eyebrow">YOUR LIFE, AT YOUR PACE</span><p>${titles[ui.page]||(ui.page==='stageOverview'?'阶段总览':'培养明细')}</p></div><div class="top-actions">${state.running?`<button type="button" class="running-pill" data-nav="today"><i></i>${e(state.running.name)} <span data-live-small></span></button>`:''}<button type="button" data-nav="settings" class="save-status" title="查看本地数据与备份"><span aria-hidden="true">◉</span> 已存本机</button></div></header>${ui.needsRecovery&&state.running?`<div class="recovery-banner"><span>上次的${e(state.running.name)}计时还开着，先核对离开期间的活动。</span><button type="button" class="secondary" data-action="recovery">核对计时</button></div>`:''}${content}<footer class="page-footer">NO GAME NO LIFE <span>·</span> 每一段真实的投入，都留在这里。</footer></main><nav class="mobile-nav" aria-label="手机主导航">${nav}</nav>`;
}
export function timeline(state,date,{memory=false}={}){
  const start=D.dayStart(date,state.timeZone),end=D.dayStart(D.addDays(date,1),state.timeZone);
  const rows=D.confirmedSessions(state).filter(s=>s.start<end&&s.end>start).map(s=>({type:'activity',at:s.start,row:s}));
  if(memory)for(const m of state.moments.filter(m=>!m.sessionId&&D.dateKey(m.at,state.timeZone)===date))rows.push({type:'moment',at:m.at,row:m});
  rows.sort((a,b)=>a.at-b.at);let lastEnd=start;
  const html=rows.map(({type,row:r})=>{
    if(type==='moment')return `<div class="timeline-row moment-row"><time>${clock(r.at,state.timeZone)}</time><span class="timeline-dot" style="--dot:#b79b64"></span><div class="row-content"><button type="button" class="row-title" data-action="moment" data-id="${e(r.id)}">${e(r.title||'生活片段')}</button>${momentContent(r)}</div><span class="tag">片段</span></div>`;
    const gap=r.start>lastEnd&&lastEnd>start?`<div class="timeline-gap">${clock(lastEnd,state.timeZone)}—${clock(r.start,state.timeZone)} <span>未记录</span></div>`:'';
    lastEnd=Math.max(lastEnd,r.end);const moments=state.moments.filter(m=>m.sessionId===r.id),isRunning=r.id===state.running?.id;
    return `${gap}<div class="timeline-row${isRunning?' running-row':''}"><time>${clock(Math.max(r.start,start),state.timeZone)}<small>${clock(Math.min(r.end,end),state.timeZone)}</small></time><span class="timeline-dot" style="--dot:${e(r.color)}"></span><div class="row-content">${isRunning?`<strong class="row-title">${e(r.name)}</strong>`:`<button type="button" class="row-title" data-action="session" data-id="${e(r.id)}">${e(r.name)}</button>`}${memory?moments.map(momentContent).join(''):''}<div class="row-meta">${e(r.category)}${isRunning?' · 计时中 · 已确认部分':''}${r.mainSkillId?' · '+e(state.skills.find(s=>s.id===r.mainSkillId)?.name??''):''}${r.precision==='minute'?' · 按分钟补记':''}${!memory&&moments.length?' · 有图文':''}</div></div><div class="row-tail"><strong>${duration((Math.min(r.end,end)-Math.max(r.start,start))/60000)}</strong>${isRunning?button('recovery','核对计时','text-button'):memory?button('moment-for-session','＋','icon-button',r.id):button('edit-session','修正','text-button',r.id)}</div></div>`;
  }).join('');
  const running=state.running&&state.running.start<end&&date===D.dateKey(Date.now(),state.timeZone)&&!rows.some(r=>r.type==='activity'&&r.row.id===state.running.id)?`<div class="timeline-row running-row"><time>${clock(Math.max(start,state.running.start),state.timeZone)}</time><span class="timeline-dot" style="--dot:#648a73"></span><div class="row-content"><strong>${e(state.running.name)}</strong><div class="row-meta">计时中 · 今天尚无已确认时段</div></div><span class="live-dot">进行中</span></div>`:'';
  return html+running||empty('这一天，还没有记录','从现在开始，也可以只补上记得清楚的一段。','add-session','补记一段');
}
export function momentContent(m){return `<div class="moment-content">${m.text?`<p>${e(m.text).replace(/\n/g,'<br>')}</p>`:''}${m.photos.length?`<div class="thumbnails">${m.photos.map((p,i)=>`<button type="button" data-action="photo" data-id="${e(m.id)}" data-index="${i}" aria-label="查看照片 ${e(p.name)}"><img src="${e(p.data)}" alt="${e(p.name)}" loading="lazy"></button>`).join('')}</div>`:''}${m.text||m.photos.length?button('moment','编辑片段','text-button',m.id):''}</div>`;}
export function dateControl(ui){return `<div class="date-control"><button type="button" data-action="prev-date" aria-label="前一天">‹</button><input type="date" aria-label="查看日期" id="view-date" value="${ui.date}"><button type="button" data-action="next-date" aria-label="后一天">›</button></div>`;}
export function today(state,ui){
  const date=D.dateKey(Date.now(),state.timeZone),stats=D.summarize(state,date,date),r=state.running;
  const plan=state.plans.find(p=>p.focus&&p.startDate<=date&&p.endDate>=date);
  return `<section class="heading"><div><span class="eyebrow">CHAPTER / ${date.slice(0,4)}</span><h1>今天，也在积累。</h1><p>${longDate(date)} <span class="dot-separator">·</span> 按自己的节奏来</p></div><div class="date-seal"><span>${date.slice(5,7)}</span><b>${date.slice(8)}</b></div></section>
  ${onboardingBanner(state)}<div class="today-grid"><section class="timer-card"><div class="card-top"><span class="eyebrow">${r?'A MOMENT IN PROGRESS':'A NEW MOMENT'}</span><span class="tiny-badge">${r?'正在记录':'从这里开始'}</span></div><div class="timer-orbit ${r?'is-running':''}"><div class="orbit-ring"></div><div class="orbit-ring second"></div><span class="orbit-spark">✦</span><div class="timer-center"><span class="timer-label">${r?e(r.name):'此刻，留给什么'}</span><div class="timer-digits" data-live>${r?'00:00:00':'00:00'}</div><span class="timer-sub">${r?clock(r.start,state.timeZone)+' 开始':'一天的记录，从这一刻开始'}</span></div></div><div class="timer-actions">${button('choose-activity',r?'⇄　切换活动':'▷　开始记录','primary timer-main')}${r?button('stop','□　停止','stop-button'):''}</div>${r?`<div class="context-controls"><span class="tag">情境：${e(state.contextSpans.find(c=>c.end===null)?.name||'未设置')}</span>${button('current-context','设置 / 结束','text-button')}${ui.nativeStatus?.available&&state.settings.phone?.enabled?button('current-phone-mode',r.phoneMode==='focus'?'专注模式':'并行模式','text-button'):''}</div>`:''}<div class="timer-caption">${r?'切换共用一个时间边界，停止后留自然空白。':'生活、休息与投入，都可以在这里记录。'}</div><div class="landscape" aria-hidden="true"><svg viewBox="0 0 600 95" preserveAspectRatio="none"><path d="M0 76L93 35L167 69L250 13L342 62L420 29L510 72L600 42V95H0Z"/><path d="M0 84L125 64L236 85L356 46L451 79L530 60L600 83V95H0Z"/></svg></div></section>
  <div class="home-side"><section class="card day-numbers"><span class="eyebrow">TODAY'S FOOTPRINT</span><h2>今天的足迹</h2>${compositionCard(state,date,{e,duration,num})}<div class="number-pair"><div><strong>${duration(stats.totalMinutes)}</strong><span>已记录</span></div><div><strong>${duration(stats.mainlineMinutes)}</strong><span>主线投入</span></div></div><div class="day-ribbon" aria-label="今日时间分布">${stats.rows.map(s=>`<span style="left:${(s.start-D.dayStart(date,state.timeZone))/864000}%;width:${Math.max(0.12,(s.end-s.start)/864000)}%;background:${e(s.color)}" title="${e(s.name)}"></span>`).join('')}</div><div class="ribbon-scale"><span>00:00</span><span>12:00</span><span>24:00</span></div></section>
  <section class="card focus-card"><div class="section-title"><h2>今日重点</h2>${button('new-plan','＋','icon-button')}</div>${plan?planCard(state,plan,true):`<div class="focus-empty"><span aria-hidden="true">⚑</span><p>给在意的事，一个位置。</p>${button('new-plan','设一个阶段重点','text-button')}</div>`}</section></div></div>
  <section class="card common-card"><div class="section-title"><div><h2>常用活动</h2><p>点一下，开始或接力</p></div><div class="inline-actions">${button('choose-activity','全部活动','secondary')}${button('manage-activities','管理','text-button')}</div></div><div class="common-grid">${state.activities.filter(a=>a.favorite&&!a.archived).map(a=>`<button type="button" class="activity-tile ${r?.activityId===a.id?'selected':''}" data-action="quick-start" data-id="${e(a.id)}"><span class="activity-symbol" style="--activity:${e(a.color)}">${a.mainSkillId?'✧':a.id==='sleep'?'☾':a.id==='meal'?'♧':'◇'}</span><span>${e(a.name)}</span>${r?.activityId===a.id?'<i aria-label="正在计时"></i>':''}</button>`).join('')||'<p class="muted">在管理中选几个常用活动。</p>'}</div></section>
  <section class="card"><div class="section-title"><div><span class="eyebrow">THE DAY UNFOLDS</span><h2>一天的经过</h2></div><div class="inline-actions">${button('add-session','＋ 补记','secondary')}${button('organize-range','整理范围','text-button')}${button('history-context','调整情境','text-button')}${button('to-memory','回看图文 ↗','text-button')}</div></div>${timeline(state,date)}${(ui.drafts||[]).filter(d=>d.kind==='records').map(d=>button('resume-range','继续整理草稿','secondary',d.id)).join('')}</section>${phoneCard(state,{e,duration,clock},true)}`;
}
export function planCard(state,p,compact=false){const v=D.planProgress(state,p);return `<div class="plan-card ${compact?'compact':''}"><div class="plan-top"><h3>${e(p.title)}</h3>${p.focus?'<span class="tag gold">今日重点</span>':''}</div><p class="muted">${p.startDate.slice(5)} — ${p.endDate.slice(5)}</p>${p.targetMinutes?`<div class="progress-caption"><strong>${duration(v.minutes)}</strong><span>/ ${duration(p.targetMinutes)}</span></div>${bar(v.ratio)}`:''}${p.outcome?`<div class="outcome-line"><span class="${p.completedAt?'done':''}">${p.completedAt?'✓':'○'}</span><p>${e(p.outcome)}</p></div>`:''}<div class="plan-actions">${p.outcome?button('complete-plan',p.completedAt?'查看达成 ✓':'确认成果完成',p.completedAt?'text-button':'secondary',p.id):''}${!compact?button('stage-overview','阶段总览 ›','secondary',p.id):''}${!compact?button('edit-plan','编辑','text-button',p.id):''}${!p.focus&&!compact?button('focus-plan','设为今日重点','text-button',p.id):''}</div></div>`;}
export function plans(state,ui){const date=D.dateKey(Date.now(),state.timeZone),active=state.plans.filter(p=>p.endDate>=date),old=state.plans.filter(p=>p.endDate<date);return `<section class="heading"><div><span class="eyebrow">SMALL STEPS, A LONG WAY</span><h1>把在意的事，往前推进。</h1><p>时间目标和成果目标，各自留下真实的进展。</p></div>${button('new-plan','＋ 新建阶段','primary')}</section><div class="plans-grid">${active.map(p=>`<section class="card">${planCard(state,p)}</section>`).join('')||empty('还没有阶段计划','可以用一周、十天，或任意一段适合你的日期。','new-plan','新建阶段')}</div>${old.length?`<section class="card"><h2>往期阶段</h2><div class="plans-grid">${old.map(p=>planCard(state,p)).join('')}</div></section>`:''}`;}
const growthPages=()=>createGrowthViews({e,num,progressNum,duration,clock,bar,button,empty});
export function growth(state,ui){return growthPages().growth(state,ui);}
export function stageOverview(state,ui){return growthPages().overview(state,ui);}
export function skillDetail(state,ui){return growthPages().skillDetail(state,ui);}
export function memory(state,ui){return diaryCollection(state,ui,{e,dateControl,momentContent});}
export function insights(state,ui){const start=ui.statsStart||D.addDays(ui.date,-6),end=ui.statsEnd||ui.date,v=D.summarize(state,start,end),days=[];for(let d=start;d<=end&&days.length<366;d=D.addDays(d,1))days.push(d);const dayStats=days.map(d=>({d,...D.summarize(state,d,d)})),max=Math.max(60,...dayStats.map(v=>v.totalMinutes));return `<section class="heading"><div><span class="eyebrow">PATTERNS OF YOUR DAYS</span><h1>时间，留下的形状。</h1><p>按实际发生的日期分配；空白自然保留。</p></div></section><section class="card"><form id="stats-range" class="range-form"><label>开始日期<input name="start" type="date" value="${start}" required></label><label>结束日期<input name="end" type="date" value="${end}" required></label><button class="secondary">查看统计</button>${button('stats-today','今日','text-button')}${button('stats-week','最近七天','text-button')}</form></section><section class="card stat-overview"><div><span>已记录</span><strong>${duration(v.totalMinutes)}</strong></div><div><span>主线投入</span><strong>${duration(v.mainlineMinutes)}</strong></div><div><span>覆盖日期</span><strong>${days.length}<small> 天</small></strong></div></section><div class="two-columns"><section class="card"><h2>活动分布</h2><div class="distribution">${Object.entries(v.byName).sort((a,b)=>b[1]-a[1]).map(([name,n])=>`<div><div class="progress-caption"><strong>${e(name)}</strong><span>${duration(n)}</span></div>${bar(n/Math.max(v.totalMinutes,1))}</div>`).join('')||empty('还没有可统计的记录','记录会自然汇集到这里。')}</div></section><section class="card"><h2>每天的投入</h2><div class="daily-chart">${dayStats.map(v=>`<div class="chart-col" title="${v.d} ${duration(v.totalMinutes)}"><span>${duration(v.totalMinutes)}</span><div class="chart-bar"><i style="height:${Math.max(1,v.totalMinutes/max*100)}%"></i></div><small>${v.d.slice(5)}</small></div>`).join('')}</div><p class="quiet-note">包含所有已确认活动。主线由活动设置决定，关联贡献不增加生活分钟。</p></section></div><section class="card"><div class="section-title"><h2>按日核对</h2>${dateControl(ui)}</div>${ui.category?`<p>${e(ui.category)} · ${button('clear-category','显示全部','text-button')}</p>`:''}${timeline(ui.category?{...state,sessions:state.sessions.filter(r=>r.category===ui.category),running:state.running?.category===ui.category?state.running:null}:state,ui.date)}</section>`;}
export function settings(state,ui){const photoCount=state.moments.reduce((n,m)=>n+m.photos.length,0);return `<section class="heading"><div><span class="eyebrow">YOUR DATA, YOUR OWN</span><h1>把记录，好好留住。</h1><p>${ui.native?'数据保存在这部手机的应用里；无需登录，也不依赖电脑。':'数据保存在当前设备、当前浏览器；换浏览器或网址会是独立空间。'}</p></div></section>${themeSettings(state)}${phoneSettings(state,ui,{e,duration,clock})}<section class="card"><div class="section-title"><h2>完整备份与恢复</h2><span class="tag">含照片</span></div><p>目前有 ${state.sessions.length} 条已结束活动、${state.moments.length} 个图文片段、${photoCount} 张照片。导出的备份包含计时、培养项、自评、阶段、图文、情境、手机记录、主题和未保存草稿。</p><div class="settings-actions">${button('backup','↓ 导出完整备份','primary')}<label class="secondary file-button">导入备份<input id="import-backup" type="file" accept=".json,application/json" hidden></label>${button('restore-point','恢复上次替换前的数据','text-button')}</div><p class="quiet-note">导入先校验并预览；替换前自动在本机保留一个恢复点。备份文件由你保存，建议定期导出到安全位置。</p></section><section class="card"><details><summary>升级与旧版兼容导出</summary><p>新版完整备份保留所有数据。以下仅用于需要旧版读取的情况，不会更改当前应用。</p><div class="settings-actions">${button('export-original','导出升级前原始备份','secondary')}${button('export-legacy','导出当前旧版兼容数据','secondary')}</div></details></section><div class="two-columns"><section class="card"><h2>设备与保存</h2><dl class="info-list"><div><dt>当前数据空间</dt><dd>${ui.native?'安卓应用 · '+APP_VERSION:e(location.origin)+' · '+APP_VERSION}</dd></div><div><dt>日期口径</dt><dd>${e(state.timeZone)} · 跨日拆分统计</dd></div><div><dt>离线资源</dt><dd id="offline-status">正在检查…</dd></div><div><dt>${ui.native?'本机存储':'浏览器存储'}</dt><dd id="storage-status">正在检查…</dd></div></dl>${ui.native?'':button('persist-storage','请求保留本地数据','secondary')}<p class="quiet-note">${ui.native?'卸载应用或清除应用数据会清除本地记录。':'清理浏览器数据会清除本地记录。'}关闭与重开会恢复已保存数据；日记与整理草稿单独保存在本机，可继续编辑。</p></section><section class="card">${ui.native?'<h2>离线使用与更新</h2><p>安装包已包含全部页面资源。记录与查看不需要电脑或网络；照片从系统文件选择器添加。</p><p>完整备份与文字导出会打开系统保存窗口，由你选择位置。网页与应用各自存储，可通过完整备份转移。</p><p class="quiet-note">更新请直接覆盖安装同签名的新版本，保留现有数据；先导出一份完整备份。不要先卸载。</p>':`<h2>浏览器试用</h2><p>可以手动计时、查看成长和保存图文。记录只在当前浏览器与网址中保存。</p><p>更换设备、浏览器或在网页与安卓应用之间转移，请使用完整备份；不会自动同步。</p><p class="quiet-note">HTTPS首次加载完成后可缓存离线资源。浏览器省电或清理数据仍会影响后台和保存，建议定期导出备份。</p>`}</section></div><section class="card"><h2>使用说明</h2><p>开始与接力都从现在计时。补记请填写确定的范围，按分钟确认也正常累计。重叠会要求先调整范围；停止后不补造活动。</p><p>重新打开运行中的计时，会让你确认离开期间是否仍在做这件事。未确认尾段不自动进入成长；已保存的事实保留。你也可以只结束到确定的时间。</p><p>照片与感受可以附在活动上；没有计时也可留独立片段。时间纠错不会删除它们。成果是否完成、能力是否达到，都需要你的明确判断。</p>${button('setup-guide','初始设置引导','secondary')}${button('manage-activities','管理活动与关联','secondary')}${button('growth-info','成长数值说明','text-button')}</section><section class="card danger-zone"><div><h2>重新开始</h2><p>清空当前数据需要输入确认文字；清空前保留本机恢复点。</p></div>${button('reset','清空当前数据','danger-button')}</section>`;}
